$primary: peer.m2-define-palette(peer.$m2-indigo-palette, 700, 200, 900, 300);
$accent: peer.m2-define-palette(peer.$m2-pink-palette, A200, A100, A400);
$warn: peer.m2-define-palette(peer.$m2-red-palette, 900);
$closeout-level: peer.m2-define-typography-level(19px, 27px, 600, 'Closeout Font', 0.03em);
$theme: peer.m2-define-light-theme((
  color: (primary: $primary, accent: $accent, warn: $warn),
  typography: peer.m2-define-typography-config($font-family: 'Custom Family', $body-1: $closeout-level, $button: $closeout-level),
  density: -2
));
.sass-argument-probe { @include peer.divider-base($theme); @include peer.divider-typography($theme); }

cases.harness:
@forward 'core/theming/theming' show define-palette, define-light-theme, define-dark-theme, get-color-config;
@forward 'core/theming/palette' show $indigo-palette, $pink-palette, $red-palette;
@forward 'core/typography/typography' show define-typography-level, define-typography-config, define-legacy-typography-config;
@forward 'divider/divider-theme' as divider-* show divider-color, divider-density, divider-theme, divider-typography;

